hooks.command:
node -e "
const fs = require('fs');
const input = JSON.parse(require('fs').readFileSync('/dev/stdin', 'utf8'));
const result = { };
process.stdout.write(JSON.stringify(result));
" 2>/dev/null || true

node -e "
const input = JSON.parse(require('fs').readFileSync('/dev/stdin', 'utf8'));
const cmd = (input.toolCall && input.toolCall.args && input.toolCall.args.CommandLine) || '';
const dangerous = ['git push --force', 'git reset --hard', 'rm -rf', 'git clean -fd', 'git push -f'];
const isDangerous = dangerous.some(d => cmd.includes(d));
if (isDangerous) {
  process.stdout.write(JSON.stringify({ decision: 'force_ask', reason: 'Potentially destructive git/rm command: ' + cmd }));
} else {
  process.stdout.write(JSON.stringify({ decision: 'allow' }));
}
"

PreInvocation.command:
node -e "
const input = JSON.parse(require('fs').readFileSync('/dev/stdin', 'utf8'));
if (input.invocationNum === 1) {
  process.stdout.write(JSON.stringify({
    injectSteps: [{ ephemeralMessage: '⚡ AGY | oma-mode active | ultrawork, hyperplan, security-research, tech-debt-audit, work-with-pr, ast-grep, github-triage skills available' }]
  }));
} else {
  process.stdout.write(JSON.stringify({ injectSteps: [] }));
}
"

Stop.command:
node -e "
const input = JSON.parse(require('fs').readFileSync('/dev/stdin', 'utf8'));
const reason = input.terminationReason || '';
if (reason === 'model_stop' && input.fullyIdle !== false) {
  process.stdout.write(JSON.stringify({ decision: '' }));
} else {
  process.stdout.write(JSON.stringify({ decision: '' }));
}
"
